Section FPX_1. Context {fx : PropExec.FPState}.

#[local] Ltac rwH :=
  repeat match goal with
         | H : getr ?rg ?i = _ |- context [getr ?rg ?i] => rewrite !H
         end.
#[local] Ltac unorm :=
  repeat match goal with
         | |- context [bv_unsigned (Z_to_bv 64 ?z)] =>
             lazymatch z with context [Z_to_bv 64 _] => fail | _ => rewrite (u_Z2bv z) by lia end
         end.
(* [comment removed for export] *)
#[local] Ltac cond :=
  rwH; unfold at_, v_addi, v_add, c_eq, c_ltu, bv_eqb, bv_ltu; imm_norm; unorm;
  first [apply Z.eqb_eq | apply Z.eqb_neq | apply Z.ltb_lt | apply Z.ltb_ge]; lia.
(* [comment removed for export] *)
#[local] Ltac wval :=
  gres; rwH; unfold at_, v_addi, v_add, v_sub; imm_norm; unorm; first [reflexivity | f_equal; lia].

(* [comment removed for export] *)
Definition kcs2 (regs regs' : bvmap 5 word) : Prop :=
  forall r : reg, In r callee_saved -> r <> 2%bv -> getr regs' r = getr regs r.
#[using="Type"] Lemma kcs2_refl : forall regs, kcs2 regs regs.
Proof.
ltac2:(KReplay.run1 (kr_t_Na0MemIsZero ()) ["FPX_1"] "h02_Hh13_H0h21rh34regsp;1p;2p;3p-1R0p10000p4p710p9P0p1000\R1p4p710p9P0P1p4p7210p9P0P1p4p73110p9P0p1001:p4p710p9g0022R0p4p7210p1002^p4p710R1p8p1003<p4p710p1004?p4p710p8p1004[p4p710P1p8p1005^p4p710P1p8p10069p4p710P1p8g006Xj10Tg00U2j1<Tg00f7j11Tg013_j12TP0j2;Tg014Bj3:Tg007=j17Tg014Yj34Tg00@?j35Tg00jGj16Tg015<j23Tg00?9j28Tg015nj29Tg00QA#0R0#<#1R1%00#0#0#0#0#1#2R2';%21R3f0R4g016l5:3f1%70g0182541553#6f3f2'3,82W1W0W21944eW3o"). Qed.
#[using="Type"] Lemma kcs2_trans : forall r1 r2 r3, kcs2 r1 r2 -> kcs2 r2 r3 -> kcs2 r1 r3.
Proof.
ltac2:(KReplay.run1 (kr_t_Na0MemIsZero ()) ["FPX_1"] "h01Ah11Bh22H2h32Hrh41bh51rh62r1h72r2h82r3p;1p;2p;3p;6p-1R0p10000p4p710p9P0p1000\R1p4p710p9P0P1p4p7210p9P0P1p4p73110p9P0p1001:p4p710p9g0022R0p4p7210g002^R1p4p710R2p8p1003<p4p710p1004?p4p710p8p1004[p4p710P2p8p1005^p4p710P2p8p10069p4p710P2p8g006Xj10Tg00U2j1<Tg00f7j13Tg013_j14TP0j2;Tg015nj25Tg014Bj3:Tg007=j18Tg014Yj37Tg00@?j32Tg00jGj16Tg015<j21TP1j69Tg00QA#0R1#<#3R0%01#0#0#0#0#3#4R2';R3f2R4f1R5'5R6%40R7f0R8g016l5:7%81g01825709275#6P2f6/14f8f3R7'19228X42f4R2P4P5P8O3f5/14P7P4P5P8O3E9W2W3W51524eX16W0X83X73W6o"). Qed.
#[using="Type"] Lemma kcs2_upd : forall regs regs' (rd : reg) v,
