  Definition mid_post (rg : bvmap 5 word) : Prop :=
    getr rg 11 = Z_to_bv 64 0 /\ getr rg 14 = Z_to_bv 64 e
    /\ getr rg 12 = Z_to_bv 64 ae /\ getr rg 10 = Z_to_bv 64 b /\ getr rg 2 = Z_to_bv 64 (s - 16) /\ getr rg 1 = ra.

