  #[using="sp Hn Happ Hs Hshs Hok kL HZ HL HkL"] Lemma c5_run : forall regs0 regs,
    c4_post regs ->
    exists regs' M',
      msteps ASEGS (mkst regs (0x8254c : word) (M7 regs0) rom) (mkst regs' (0x82560 : word) M' rom)
