        | rewrite length_N_to_le_bytes; cbn [Z.of_nat Pos.to_nat]; unorm; lia ].
  #[local] Ltac slot := repeat peel; apply rdn_wbytes_hit8; unorm; lia.
  #[using="pd ps n fS lS fD lD Hs"] Lemma M10_FR : forall regs0, FR regs0 (M10 regs0).
Proof.
