  Definition c1_post (rg : bvmap 5 word) : Prop :=
    getr rg 10 = Z_to_bv 64 K /\ getr rg 9 = Z_to_bv 64 n /\ getr rg 18 = Z_to_bv 64 p /\ getr rg 8 = Z_to_bv 64 s
    /\ getr rg 2 = Z_to_bv 64 (s - 2144).
